import{_ as e,o as s,c as r,a2 as i}from"./chunks/framework.DPTp4bo7.js";const u=JSON.parse('{"title":"物流原理与前沿研究","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://kokobird28144.github.io/endfield-skydoc/zh/logistics-principles-and-frontier-research"}],["link",{"rel":"alternate","hreflang":"en","href":"https://kokobird28144.github.io/endfield-skydoc/logistics-principles-and-frontier-research"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://kokobird28144.github.io/endfield-skydoc/zh/logistics-principles-and-frontier-research"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://kokobird28144.github.io/endfield-skydoc/logistics-principles-and-frontier-research"}]]},"headers":[],"relativePath":"zh/logistics-principles-and-frontier-research.md","filePath":"zh/page-Ul3PjfHfEH7t9ofd3SfA1L.md"}'),n={name:"zh/logistics-principles-and-frontier-research.md"};function o(t,a,c,l,d,h){return s(),r("div",null,[...a[0]||(a[0]=[i('<div class="logistics-content"><span class="logistics-source-anchor" id="物流原理与前沿研究" aria-hidden="true"></span><h1 id="物流原理与前沿研究" tabindex="-1">物流原理与前沿研究 <a class="header-anchor" href="#物流原理与前沿研究" aria-label="Permalink to &quot;物流原理与前沿研究&quot;">​</a></h1><blockquote><p>源页面 ID：<code>Ul3PjfHfEH7t9ofd3SfA1L</code> ｜ <a href="https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=Ul3PjfHfEH7t9ofd3SfA1L" target="_blank" rel="noreferrer">在腾讯文档中打开</a></p></blockquote><p><span class="mark-red"><strong>十分严重的缺乏维护，应当讨论该子页面下目录是否合理</strong></span></p><p><span id="source-block-3MTsTMyenCW20YTMnFSi65"></span></p><span class="logistics-source-anchor" id="流量转化" aria-hidden="true"></span><h2 id="流量转化" tabindex="-1">流量转化 <a class="header-anchor" href="#流量转化" aria-label="Permalink to &quot;流量转化&quot;">​</a></h2><p><span id="source-block-wO7xPIiHDJwfeAtqFW4VJE"></span></p><span class="logistics-source-anchor" id="均匀性与极差" aria-hidden="true"></span><h2 id="均匀性与极差" tabindex="-1">均匀性与极差 <a class="header-anchor" href="#均匀性与极差" aria-label="Permalink to &quot;均匀性与极差&quot;">​</a></h2><p><span id="source-block-f5f4WE5OyQHLDbhWbKgmAv"></span></p><span class="logistics-source-anchor" id="滤波器" aria-hidden="true"></span><h2 id="滤波器" tabindex="-1">滤波器 <a class="header-anchor" href="#滤波器" aria-label="Permalink to &quot;滤波器&quot;">​</a></h2><p>狭义滤波器：将输入的不均匀序列转化为更加均匀的序列，例如将10110 10011转化为10110 10110，有时也被叫做稳流器</p><p>在满带输入的情况下等同于某种较为均匀的限流器</p><p>广义滤波器：低通：将超过设定流量范围的序列流放到其他地方，通常为插入低于设定流量范围的序列中或者流出结构。高通：与低通相反。</p><p><span id="source-block-9j2XLqzFcpwJ8W5QQIYeRK"></span></p><span class="logistics-source-anchor" id="整流器" aria-hidden="true"></span><h2 id="整流器" tabindex="-1">整流器 <a class="header-anchor" href="#整流器" aria-label="Permalink to &quot;整流器&quot;">​</a></h2><p>狭义整流器：将输入的序列转化为连续1/0序列，例如将10110 10011转化为11100 11100</p><p>在满带输入下对上游传递连续1/0序列的阻塞信号</p><p>广义整流器：将输入流转化为特定结构流量，典型的是转化为连续流和0流量，还有转化为特定序列，例如完美均匀序列</p><p><span id="source-block-dey4t7kblTAWoIHHqzUYE7"></span></p><span class="logistics-source-anchor" id="溢流器" aria-hidden="true"></span><h2 id="溢流器" tabindex="-1">溢流器 <a class="header-anchor" href="#溢流器" aria-label="Permalink to &quot;溢流器&quot;">​</a></h2><p>狭义溢流器：输入在两个输出口之间有严格优先级关系，即在A没有满到无法输出前B都不会有流量。</p><p>广义溢流器：输入在两个输出口之间有不严格优先级关系，即输出到A方向的流量大于A最大通行流量。</p><p><span id="source-block-S59ZGmLv5iYu3bJX0M4vLU"></span></p><span class="logistics-source-anchor" id="bresenham算法" aria-hidden="true"></span><h2 id="bresenham算法" tabindex="-1">Bresenham算法 <a class="header-anchor" href="#bresenham算法" aria-label="Permalink to &quot;Bresenham算法&quot;">​</a></h2><p><span id="source-block-BKd0bfBqMQYjGOon5TjRNh"></span></p><span class="logistics-source-anchor" id="均匀二进制分流器" aria-hidden="true"></span><h2 id="均匀二进制分流器" tabindex="-1">均匀二进制分流器 <a class="header-anchor" href="#均匀二进制分流器" aria-label="Permalink to &quot;均匀二进制分流器&quot;">​</a></h2><p><span id="source-block-rJLuoyW0sbNOPnKggEQMI8"></span></p><span class="logistics-source-anchor" id="简单有理分流器的均匀性" aria-hidden="true"></span><h2 id="简单有理分流器的均匀性" tabindex="-1">简单有理分流器的均匀性 <a class="header-anchor" href="#简单有理分流器的均匀性" aria-label="Permalink to &quot;简单有理分流器的均匀性&quot;">​</a></h2><p><span id="source-block-saFuJ384PvuWkO0x5E0uld"></span></p><span class="logistics-source-anchor" id="均匀有理限流器" aria-hidden="true"></span><h2 id="均匀有理限流器" tabindex="-1">均匀有理限流器 <a class="header-anchor" href="#均匀有理限流器" aria-label="Permalink to &quot;均匀有理限流器&quot;">​</a></h2><p><span id="source-block-Uj5kS4ulgYdVqCL6baJ4Ku"></span></p><span class="logistics-source-anchor" id="闰年算法" aria-hidden="true"></span><h3 id="闰年算法" tabindex="-1">闰年算法 <a class="header-anchor" href="#闰年算法" aria-label="Permalink to &quot;闰年算法&quot;">​</a></h3><p><span id="source-block-SmEDFRTyh8P5P9V7gXt3Kh"></span></p><span class="logistics-source-anchor" id="欧拉算法" aria-hidden="true"></span><h3 id="欧拉算法" tabindex="-1">欧拉算法 <a class="header-anchor" href="#欧拉算法" aria-label="Permalink to &quot;欧拉算法&quot;">​</a></h3><p><span id="source-block-xQRRd0h5FlKNP3iUeDlYjq"></span></p><span class="logistics-source-anchor" id="古典物流理论" aria-hidden="true"></span><h2 id="古典物流理论" tabindex="-1">古典物流理论 <a class="header-anchor" href="#古典物流理论" aria-label="Permalink to &quot;古典物流理论&quot;">​</a></h2></div>',1)])])}const f=e(n,[["render",o]]);export{u as __pageData,f as default};
